// 科技信息 · 风格样片。标准分镜：标题 → 要点 → 数据 → 人名条 → 收尾。
// 可照搬：STYLE 取值、grid()（底纹网格）、brackets()（角标框）、typeOn()（等宽逐字打出）、
// rollNumber()（数字滚动）、lineChart()（折线生长）、wipe()（转场横扫），以及 layers() 的分层写法：
// 会位移、会伸展的元素各成一层（标题滑入用固定遮罩 clip），运行时据此做运动模糊；逐字打出、计数这类内容变化留在静止层。

const STYLE = {
  color: {
    bg: "#0A0F1A",
    panel: "rgba(120,160,220,0.06)",
    grid: "rgba(120,160,220,0.07)",
    text: "#E6EDF7",
    muted: "#7C8BA1",
    accent: "#3BE0A0", // 主强调：状态、进度、高亮
    info: "#4DA3FF", // 语义色：仅用于第二条数据或链接，和强调色不同时大面积出现
  },
  font: {
    title: '"HarmonyOS Sans SC", "MiSans", "Source Han Sans SC", "Microsoft YaHei", sans-serif',
    mono: '"JetBrains Mono", "Cascadia Mono", "Consolas", monospace',
  },
};

const SCENES = { title: [0, 1.85], list: [1.85, 3.85], data: [3.85, 5.65], name: [5.65, 6.95], end: [6.95, 8] };
const COPY = {
  title: "把想法变成画面",
  subtitle: "风格样片 · STYLE SAMPLE",
  list: ["统一的配色", "统一的字体", "统一的节奏"],
  data: { value: 87, unit: "%", label: "一次通过率" },
  name: { name: "痕继痕迹", role: "动效设计师", tag: "MOTION DESIGNER" },
  end: "一个风格，处处一致",
};

const clamp = (v) => Math.max(0, Math.min(1, v));
const quartOut = (v) => 1 - Math.pow(1 - clamp(v), 4);
const quintOut = (v) => 1 - Math.pow(1 - clamp(v), 5);
const cubicIn = (v) => clamp(v) ** 3;
const font = (weight, size, family) => `${weight} ${Math.round(size)}px ${family}`;

// 干脆：入场 0.45 s quartOut，离场 0.2 s cubicIn。
function phase(t, [a, b], delay = 0, inDur = 0.45, outDur = 0.2) {
  return { enter: quartOut((t - a - delay) / inDur), leave: cubicIn((t - (b - outDur)) / outDur), on: t >= a && t < b };
}

function grid(ctx, t, u, w, h) {
  const step = 40 * u;
  // 网格极慢平移，只做底纹，不抢主体。
  const off = (t * 6 * u) % step;
  ctx.fillStyle = STYLE.color.grid;
  for (let x = -off; x < w; x += step) ctx.fillRect(x, 0, Math.max(1, u), h);
  for (let y = -off; y < h; y += step) ctx.fillRect(0, y, w, Math.max(1, u));
  const fade = ctx.createLinearGradient(0, 0, 0, h);
  fade.addColorStop(0, "rgba(10,15,26,0.85)");
  fade.addColorStop(0.35, "rgba(10,15,26,0)");
  fade.addColorStop(0.65, "rgba(10,15,26,0)");
  fade.addColorStop(1, "rgba(10,15,26,0.85)");
  ctx.fillStyle = fade;
  ctx.fillRect(0, 0, w, h);
}

// 四角角标：线段从角向两边长出。
function brackets(ctx, x, y, bw, bh, len, k, u, color = STYLE.color.accent) {
  const l = len * k, lw = Math.max(1, 1.5 * u);
  ctx.fillStyle = color;
  for (const [cx, cy, sx, sy] of [[x, y, 1, 1], [x + bw, y, -1, 1], [x, y + bh, 1, -1], [x + bw, y + bh, -1, -1]]) {
    ctx.fillRect(sx > 0 ? cx : cx - l, cy - (sy > 0 ? 0 : lw), l, lw);
    ctx.fillRect(cx - (sx > 0 ? 0 : lw), sy > 0 ? cy : cy - l, lw, l);
  }
}

// 等宽逐字打出，末尾带光标块。
function typeOn(ctx, text, x, y, k, u, cursor = true) {
  const n = Math.floor(text.length * clamp(k));
  ctx.fillText(text.slice(0, n), x, y);
  if (cursor && k > 0 && k < 1.15) {
    const cw = ctx.measureText(text.slice(0, n)).width;
    ctx.fillRect(x + cw + 2 * u, y - 11 * u, 7 * u, 13 * u);
  }
}

function rollNumber(value, k) {
  return (value * quintOut(k)).toFixed(1);
}

// 横扫转场：一条强调色的竖线从左扫到右，线后是新场景。本地坐标原点在竖线上，位置由 pose 给出。
const WIPE_DUR = 0.28;
function wipe(ctx, u, h) {
  ctx.fillStyle = STYLE.color.accent;
  ctx.fillRect(0, 0, 2 * u, h);
  ctx.fillStyle = "rgba(59,224,160,0.08)";
  ctx.fillRect(-60 * u, 0, 60 * u, h);
}

function lineChart(ctx, x, y, cw, ch, k, u) {
  const pts = [0.12, 0.2, 0.18, 0.34, 0.31, 0.46, 0.58, 0.55, 0.71, 0.87];
  ctx.strokeStyle = STYLE.color.grid;
  ctx.lineWidth = Math.max(1, u);
  for (let i = 0; i <= 4; i++) { ctx.beginPath(); ctx.moveTo(x, y + (ch * i) / 4); ctx.lineTo(x + cw, y + (ch * i) / 4); ctx.stroke(); }
  const n = (pts.length - 1) * clamp(k);
  ctx.strokeStyle = STYLE.color.accent;
  ctx.lineWidth = 2.5 * u;
  ctx.lineJoin = "round";
  ctx.beginPath();
  let px = x, py = y + ch;
  for (let i = 0; i <= Math.floor(n); i++) {
    px = x + (cw * i) / (pts.length - 1); py = y + ch * (1 - pts[i]);
    i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
  }
  const f = n - Math.floor(n), i = Math.floor(n);
  if (i < pts.length - 1) {
    px += (cw / (pts.length - 1)) * f;
    py = y + ch * (1 - (pts[i] + (pts[i + 1] - pts[i]) * f));
    ctx.lineTo(px, py);
  }
  ctx.stroke();
  // 末端光点
  ctx.fillStyle = STYLE.color.accent;
  ctx.beginPath(); ctx.arc(px, py, 5 * u, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = "rgba(59,224,160,0.2)";
  ctx.beginPath(); ctx.arc(px, py, 12 * u, 0, Math.PI * 2); ctx.fill();
}

function dataStatic(ctx, t, u, w, h) {
  const s = SCENES.data;
  if (t < s[0] || t >= s[1]) return;
  const p = phase(t, s), x = w * 0.1, k = (t - s[0] - 0.1) / 1.2;
  ctx.globalAlpha = 1 - p.leave;
  ctx.fillStyle = STYLE.color.muted;
  ctx.font = font(500, 13 * u, STYLE.font.mono);
  ctx.fillText("PASS_RATE · 一次通过率", x, h * 0.3);
  ctx.fillStyle = STYLE.color.text;
  ctx.font = font(700, 120 * u, STYLE.font.mono);
  const num = rollNumber(COPY.data.value, k);
  ctx.fillText(num, x, h * 0.3 + 128 * u);
  const nw = ctx.measureText(num).width;
  ctx.fillStyle = STYLE.color.accent;
  ctx.font = font(500, 40 * u, STYLE.font.mono);
  ctx.fillText(COPY.data.unit, x + nw + 10 * u, h * 0.3 + 128 * u);
  ctx.fillStyle = STYLE.color.accent;
  ctx.font = font(500, 14 * u, STYLE.font.mono);
  ctx.fillText(`▲ +${(12.4 * quintOut(k)).toFixed(1)} pts`, x, h * 0.3 + 168 * u);
  lineChart(ctx, w * 0.52, h * 0.3, w * 0.38, h * 0.4, k, u);
  brackets(ctx, w * 0.52 - 16 * u, h * 0.3 - 16 * u, w * 0.38 + 32 * u, h * 0.4 + 32 * u, 14 * u, p.enter, u, STYLE.color.muted);
  ctx.globalAlpha = 1;
}

function nameStatic(ctx, t, u, w, h) {
  const s = SCENES.name;
  if (t < s[0] || t >= s[1]) return;
  const p = phase(t, s), x = w * 0.1, y = h * 0.72, bw = 300 * u, bh = 84 * u;
  ctx.globalAlpha = 1 - p.leave;
  ctx.fillStyle = "rgba(10,15,26,0.9)";
  ctx.fillRect(x, y, bw * p.enter, bh);
  ctx.fillStyle = STYLE.color.accent;
  ctx.fillRect(x, y, 4 * u, bh * p.enter);
  ctx.save();
  ctx.beginPath(); ctx.rect(x, y, bw * p.enter, bh); ctx.clip();
  ctx.fillStyle = STYLE.color.text;
  ctx.font = font(700, 30 * u, STYLE.font.title);
  ctx.fillText(COPY.name.name, x + 24 * u, y + 40 * u);
  ctx.fillStyle = STYLE.color.muted;
  ctx.font = font(400, 15 * u, STYLE.font.title);
  ctx.fillText(COPY.name.role, x + 24 * u, y + 66 * u);
  ctx.fillStyle = STYLE.color.accent;
  ctx.font = font(500, 11 * u, STYLE.font.mono);
  ctx.fillText(COPY.name.tag, x + 110 * u, y + 66 * u);
  ctx.restore();
  ctx.globalAlpha = 1;
}

function endStatic(ctx, t, u, w, h) {
  const s = SCENES.end;
  if (t < s[0]) return;
  ctx.fillStyle = STYLE.color.accent;
  ctx.font = font(500, 14 * u, STYLE.font.mono);
  const label = "STYLE_LOCKED";
  const lw = ctx.measureText(label).width;
  typeOn(ctx, label, w / 2 - lw / 2, h / 2 + 52 * u, (t - s[0] - 0.25) / 0.4, u, Math.floor(t * 2) % 2 === 0);
  brackets(ctx, w / 2 - 300 * u, h / 2 - 70 * u, 600 * u, 150 * u, 20 * u, phase(t, [s[0], 99], 0.15).enter, u);
}

const within = (t, [a, b]) => t >= a && t < b;

function layers(_params, w, h) {
  const u = h / 720, out = [], x = w * 0.1;
  // 底：底色与缓慢平移的网格，整层按当前时刻画。
  out.push({ draw: (ctx, t) => { ctx.fillStyle = STYLE.color.bg; ctx.fillRect(0, 0, w, h); grid(ctx, t, u, w, h); } });

  // 标题卡：提示行逐字打出、角标长出（静止层）；大标题从左侧滑入，遮罩固定不动。
  const title = SCENES.title, ty = h * 0.5;
  out.push({
    draw: (ctx, t) => {
      if (!within(t, title)) return;
      const p = phase(t, title);
      ctx.globalAlpha = 1 - p.leave;
      ctx.fillStyle = STYLE.color.accent;
      ctx.font = font(500, 14 * u, STYLE.font.mono);
      typeOn(ctx, "> style_sample --version 1.0", x, ty - 78 * u, (t - 0.05) / 0.6, u);
      ctx.fillStyle = STYLE.color.muted;
      ctx.font = font(400, 15 * u, STYLE.font.mono);
      ctx.globalAlpha = phase(t, title, 0.35).enter * (1 - p.leave);
      ctx.fillText("风格样片 / STYLE SAMPLE", x, ty + 42 * u);
      ctx.globalAlpha = 1 - p.leave;
      brackets(ctx, x - 28 * u, ty - 120 * u, 640 * u, 200 * u, 22 * u, phase(t, title, 0.25).enter, u);
      ctx.globalAlpha = 1;
    },
  });
  out.push({
    bounds: [0, -70 * u, 620 * u, 20 * u],
    clip: [x, ty - 70 * u, w, ty + 20 * u],
    pose: (t) => within(t, title) ? { x: x - (1 - phase(t, title, 0.15).enter) * 120 * u, y: ty, opacity: 1 - phase(t, title).leave } : null,
    draw: (ctx) => {
      ctx.fillStyle = STYLE.color.text;
      ctx.font = font(700, 66 * u, STYLE.font.title);
      ctx.fillText(COPY.title, 0, 0);
    },
  });

  // 要点：淡面板条向右伸展（scaleX），条目文字从右侧滑入；勾选框、编号、OK 在静止层。
  const list = SCENES.list, top = h * 0.3, rowH = 92 * u, rw = w * 0.6;
  const listOut = (t) => 1 - cubicIn((t - (list[1] - 0.2)) / 0.2);
  COPY.list.forEach((item, i) => {
    const y = top + i * rowH, box = 22 * u, bx = x + 22 * u, mid = y + (rowH - 12 * u) / 2;
    out.push({
      bounds: [0, 0, rw, rowH - 12 * u + Math.max(1, u)],
      pose: (t) => {
        const e = phase(t, list, 0.12 + i * 0.12).enter;
        return within(t, list) && e > 0.002 ? { x, y, scaleX: e, scaleY: 1, opacity: listOut(t) } : null;
      },
      draw: (ctx) => {
        ctx.fillStyle = STYLE.color.panel;
        ctx.fillRect(0, 0, rw, rowH - 12 * u);
        ctx.fillStyle = STYLE.color.grid;
        ctx.fillRect(0, rowH - 12 * u, rw, Math.max(1, u));
      },
    });
    out.push({
      draw: (ctx, t) => {
        if (!within(t, list)) return;
        const p = phase(t, list, 0.12 + i * 0.12), o = listOut(t);
        ctx.globalAlpha = o;
        if (i === 0) {
          ctx.fillStyle = STYLE.color.muted;
          ctx.font = font(500, 13 * u, STYLE.font.mono);
          ctx.fillText("// CHECKLIST", x, top - 24 * u);
        }
        ctx.globalAlpha = p.enter * o;
        ctx.strokeStyle = STYLE.color.accent;
        ctx.lineWidth = 1.5 * u;
        ctx.strokeRect(bx, mid - box / 2, box, box);
        const fill = quartOut((t - list[0] - 0.45 - i * 0.12) / 0.25);
        ctx.fillStyle = STYLE.color.accent;
        ctx.fillRect(bx + 5 * u, mid - box / 2 + 5 * u, (box - 10 * u) * fill, box - 10 * u);
        ctx.fillStyle = STYLE.color.muted;
        ctx.font = font(500, 14 * u, STYLE.font.mono);
        ctx.fillText(`[0${i + 1}]`, bx + box + 22 * u, mid + 5 * u);
        ctx.fillStyle = STYLE.color.accent;
        ctx.font = font(500, 13 * u, STYLE.font.mono);
        ctx.textAlign = "right";
        if (fill > 0.99) ctx.fillText("OK", x + rw - 22 * u, mid + 5 * u);
        ctx.textAlign = "left";
        ctx.globalAlpha = 1;
      },
    });
    out.push({
      bounds: [0, -30 * u, 260 * u, 12 * u],
      pose: (t) => {
        const p = phase(t, list, 0.12 + i * 0.12);
        return within(t, list) && p.enter > 0 ? { x: bx + box + 86 * u + (1 - p.enter) * 30 * u, y: mid + 11 * u, opacity: p.enter * listOut(t) } : null;
      },
      draw: (ctx) => {
        ctx.fillStyle = STYLE.color.text;
        ctx.font = font(500, 32 * u, STYLE.font.title);
        ctx.fillText(item, 0, 0);
      },
    });
  });

  // 数据、人名条：数字滚动、折线生长、底条展开都是内容变化，放在静止层。
  out.push({ draw: (ctx, t) => dataStatic(ctx, t, u, w, h) });
  out.push({ draw: (ctx, t) => nameStatic(ctx, t, u, w, h) });

  // 收尾：一句话轻轻上浮入场；状态标签与角标在静止层。
  const end = SCENES.end;
  out.push({
    bounds: [-260 * u, -44 * u, 260 * u, 14 * u],
    pose: (t) => {
      const e = phase(t, [end[0], 99], 0.05).enter;
      return t >= end[0] && e > 0 ? { x: w / 2, y: h / 2 + 4 * u + (1 - e) * 16 * u, opacity: e } : null;
    },
    draw: (ctx) => {
      ctx.textAlign = "center";
      ctx.fillStyle = STYLE.color.text;
      ctx.font = font(700, 48 * u, STYLE.font.title);
      ctx.fillText(COPY.end, 0, 0);
      ctx.textAlign = "left";
    },
  });
  out.push({ draw: (ctx, t) => endStatic(ctx, t, u, w, h) });

  // 转场扫线：每个场景开头从左到右扫过整个画面，速度很快，模糊最明显。
  for (const at of [SCENES.list[0], SCENES.data[0], SCENES.name[0], SCENES.end[0]]) {
    const start = at - 0.14;
    out.push({
      bounds: [-60 * u, 0, 2 * u, h],
      pose: (t) => {
        const k = clamp((t - start) / WIPE_DUR);
        return k > 0 && k < 1 ? { x: w * quartOut(k), y: 0 } : null;
      },
      draw: (ctx) => wipe(ctx, u, h),
    });
  }
  return out;
}

export default {
  name: "科技信息 · 样片", kind: "generator", mode: "dynamic",
  nameEnglish: "Tech Info · Sample",
  params: [],
  // 动作干脆，快门用 180° 即可；扫线这类极快的元素会自然拖出长影。
  motionBlur: { shutter: 180 },
  layers,
};
